# Apply the transformation: find enclosed regions and fill with 4
def transform(grid):
    """For each cell with value equal to background, check if ALL 4 boundaries are boundary color. If so, change to 4."""

    # Find the background color (most common) and boundary color (the other non-background)
    counts = {}
    for row in grid:
        for c in row:
            counts[c] = counts.get(c, 0) + 1

    bg_color = max(counts.items(), key=lambda x: x[1])[0]
    boundary_color = next(k for k in counts if k != bg_color)
    fill_color = 4

    result = [row[:] for row in grid]  # Deep copy

    def get_boundary_in_direction(r, c, direction, grid, target):
        dr, dc = direction
        nr, nc = r + dr, c + dc
        while 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            if grid[nr][nc] != target:
                return (nr, nc), grid[nr][nc]
            nr, nc = nr + dr, nc + dc
        return None, None

    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == bg_color:
                all_boundary = True
                for dr, dc in directions:
                    boundary_pos, val = get_boundary_in_direction(r, c, (dr, dc), grid, bg_color)
                    if boundary_pos is None:
                        all_boundary = False
                        break
                    br, bc = boundary_pos
                    if val != boundary_color:
                        all_boundary = False
                        break
                if all_boundary:
                    result[r][c] = fill_color

    return result

result = transform(test_input)

